#pragma once

#include "native_input_bridge.hpp"

#include <cstddef>
#include <cstdint>
#include <mutex>
#include <string>
#include <unordered_map>

namespace tjra {

// Evidence is obtained ONLY from the trusted, mutually authenticated
// transport. It must never be assembled from RFB wire data or from a VNC
// password check. session_id must be securely generated by the server;
// channel_binding_id must uniquely identify this live authenticated channel.
struct AuthenticatedChannelEvidence {
    std::string principal_id;
    std::string channel_binding_id;
    std::string session_id;
};

struct AuthenticatedChannelSweepResult {
    std::size_t disconnected = 0;
    bool input_release_required = false;
    std::uint64_t release_epoch = 0;
};

// The future mTLS transport owns this attestor and the physical connection
// lifetime. Implementations MUST pin the verified transport handle until
// callback completion and MUST NOT reuse handles while a session is live.
// Return false on closed channels, expired credentials or verification error.
// This callback is a TRUST CONTRACT, not an implementation of mTLS.
using TrustedChannelAttestor =
    bool (*)(void* context, std::uint64_t connection_handle,
             AuthenticatedChannelEvidence* evidence);

// Policy glue between a trusted transport and EngineSessionGate. Does not
// create sockets, trust client-provided claims, inject input, release keys,
// or replace per-connection TLS authentication or Windows IPC ACLs.
//
// The coordinator owns the ONLY approved calls to the associated gate during
// a gateway connection lifetime. Callbacks must be bounded, non-reentrant,
// and must not call back into the coordinator.
class AuthenticatedSessionCoordinator final {
public:
    AuthenticatedSessionCoordinator(EngineSessionGate& gate,
                                    TrustedChannelAttestor attest,
                                    void* attestor_context) noexcept;
    ~AuthenticatedSessionCoordinator();

    AuthenticatedSessionCoordinator(const AuthenticatedSessionCoordinator&) = delete;
    AuthenticatedSessionCoordinator& operator=(const AuthenticatedSessionCoordinator&) = delete;

    Result Reserve(std::uint64_t connection_handle,
                   Clock::time_point deadline, Clock::time_point now);
    Result Attach(std::uint64_t connection_handle, Clock::time_point now);
    Result GrantControl(std::uint64_t connection_handle);

    // All input sequences and control epochs are minted on the server side;
    // the untrusted RFB client is never allowed to provide them. The sink is
    // called only after authorization by the gate under the same lock.
    InputDispatchResult DispatchInput(std::uint64_t connection_handle,
                                      const NativeInputEvent& event,
                                      TrustedNativeInputSink trusted_sink,
                                      void* sink_context);

    // Disconnect succeeds regardless of transport attestation failure,
    // allowing cleanup after a client has already disappeared. The caller
    // MUST request physical key/button release when required.
    EndResult Disconnect(std::uint64_t connection_handle);
    std::size_t ExpireReservations(Clock::time_point now);
    // Re-attest every live channel and remove closed/replaced bindings.
    // The privileged agent MUST release keys/buttons if indicated.
    AuthenticatedChannelSweepResult SweepDisconnectedChannels();

    std::size_t ActiveConnections() const;

private:
    struct Binding {
        AuthenticatedChannelEvidence evidence;
        Clock::time_point deadline{};
        bool attached = false;
        std::uint64_t last_server_sequence = 0;
    };

    static bool ValidEvidence(const AuthenticatedChannelEvidence& e) noexcept;
    bool AttestLocked(std::uint64_t connection_handle,
                      AuthenticatedChannelEvidence* out) const noexcept;
    bool SameBindingLocked(std::uint64_t connection_handle,
                           const Binding& bound) const noexcept;
    EndResult DisconnectLocked(std::uint64_t connection_handle);
    std::size_t ExpireReservationsLocked(Clock::time_point now);

    mutable std::mutex mu_;
    EngineSessionGate& gate_;
    NativeInputBridge input_;
    TrustedChannelAttestor attest_;
    void* attestor_context_;
    std::unordered_map<std::uint64_t, Binding> connections_;
};

} // namespace tjra
